@parser.command(
    argument("new_api_key", help="Api key to set as currently logged in user"),
    usage="vastai set api-key APIKEY",
    help="Set api-key (get your api-key from the console/CLI)",
)
def set__api_key(args):
    """Set the api-key."""
    from vastai.cli.util import APIKEY_FILE, APIKEY_FILE_HOME

    with open(APIKEY_FILE, "w") as writer:
        writer.write(args.new_api_key)
    print("Your api key has been saved in {}".format(APIKEY_FILE))

    if os.path.exists(APIKEY_FILE_HOME):
        os.remove(APIKEY_FILE_HOME)
        if getattr(args, "explain", False):
            print("Removed legacy api key file at {} (no longer used).".format(APIKEY_FILE_HOME))

    env_key = os.environ.get("VAST_API_KEY")
    if env_key:
        print(f"\n{WARN} VAST_API_KEY is set in your environment (ends in {format_key_suffix(env_key)}) and overrides the key you just saved.")
        print("Unset VAST_API_KEY to use the saved key.")

def xdg_config_home() -> Path:
    """Return a Path corresponding to XDG_CONFIG_HOME."""
    return _path_from_env("XDG_CONFIG_HOME", Path.home() / ".config")
